#ifdef FULLMAG_DTQ_CI_LEAF_DIAGNOSTIC
void run_dtq_ci_regular_stroud_probe(
    const mfem::Mesh &mesh,
    const mfem::GridFunction &current,
    const std::vector<std::array<double, 3>> &targets,
    const DirectTetraQuadratureOptions &options)
{
    using Point = std::array<double, 3>;
    require(options.base_quadrature_order == 8 &&
            options.maximum_subdivision_depth == 6 &&
            options.absolute_tolerance_apm == 1.0e-9 &&
            options.relative_tolerance == 1.0e-5 &&
            options.maximum_source_target_pairs == 1'000'000,
        "Stroud probe must preserve the original fixture parameters");
    require(targets.size() == 3, "Stroud probe requires exactly three original targets");
    require(mesh.GetNE() == 6, "Stroud probe requires exactly six source roots");
    const auto limits = DirectTetraQuadrature::ResolveWorkLimits(options);
    require(limits.maximum_kernel_evaluations == 100'000'000 &&
            limits.maximum_ledger_leaf_visits == 100'000'000,
        "Stroud probe must preserve the original per-call work caps");
    // Values are pinned from the independent rectangular-surface cube oracle.
    const std::array<Point, 3> reference{{
        {0.0, 0.3221687800576061, 0.0},
        {0.0, 0.21031957139483323, 0.21031957139483337},
        {0.0, 0.0, 0.0}}};
    const std::array<Point, 3> expected_targets{{
        {0.75, 0.5, 0.25},
        {2.0 / 3.0, 2.0 / 3.0, 1.0 / 3.0},
        {0.5, 0.5, 0.5}}};
    require(std::equal(targets.begin(), targets.end(), expected_targets.begin()),
        "Stroud probe target geometry differs from the pinned cube oracle");
    const std::array<const char *, 3> names{{"interior", "face", "edge"}};
    std::cerr << std::setprecision(std::numeric_limits<double>::max_digits10);
    const auto print_point = [](const Point &point) {
        std::cerr << '(' << point[0] << ',' << point[1] << ',' << point[2] << ')';
    };
    std::cerr << "OE-F1 STROUD_PROBE CONFIG variant=regular_stroud_order_gt20"
              << " base_order=" << options.base_quadrature_order
              << " maximum_depth=" << options.maximum_subdivision_depth
              << " absolute_tolerance_apm=" << options.absolute_tolerance_apm
              << " relative_tolerance=" << options.relative_tolerance
              << " pair_cap=" << options.maximum_source_target_pairs
              << " kernel_cap=" << limits.maximum_kernel_evaluations
              << " ledger_cap=" << limits.maximum_ledger_leaf_visits
              << " maximum_additional_calls=4\n";

    struct ProbeScope {
        ProbeScope() noexcept
        {
            fullmag::fem::oersted::set_dtq_ci_regular_stroud_probe(true);
        }
        ~ProbeScope()
        {
            fullmag::fem::oersted::set_dtq_ci_regular_stroud_probe(false);
        }
    } probe_scope;
    using Clock = std::chrono::steady_clock;
    const auto probe_start = Clock::now();
    std::size_t calls = 0;
    struct CallOutcome {
        bool converged;
        bool reference_pass;
    };
    const auto run = [&](const char *variant, const std::vector<Point> &call_targets,
                         std::size_t first_reference) -> CallOutcome {
        require(calls < 4, "Stroud probe exceeded four additional calls");
        ++calls;
        const auto start = Clock::now();
        const auto elapsed = [&]() {
            return std::chrono::duration<double>(Clock::now() - start).count();
        };
        std::cerr << "OE-F1 STROUD_PROBE BEGIN variant=" << variant
                  << " call=" << calls << " target_count=" << call_targets.size() << '\n';
        fullmag::fem::oersted::DirectTetraQuadratureResult result;
        try {
            // Each call has the same fresh WorkBudget; no retry or cap escalation.
            result = DirectTetraQuadrature::EvaluateField(mesh, current, call_targets, options);
        } catch (const std::exception &error) {
            std::cerr << "OE-F1 STROUD_PROBE CALL variant=" << variant
                      << " call=" << calls << " status=REFUSED elapsed_s=" << elapsed()
                      << " exception=" << std::quoted(std::string(error.what()).substr(0, 2048))
                      << '\n';
            for (std::size_t local = 0; local < call_targets.size(); ++local) {
                const auto index = first_reference + local;
                std::cerr << "OE-F1 STROUD_PROBE TARGET variant=" << variant
                          << " call=" << calls << " case=" << names[index]
                          << " status=UNAVAILABLE_AFTER_CALL_REFUSAL target_m=";
                print_point(call_targets[local]);
                std::cerr << " reference_h_apm=";
                print_point(reference[index]);
                std::cerr << " reference_tolerance_apm="
                          << std::fma(options.relative_tolerance,
                                 field_distance(reference[index], Point{}),
                                 options.absolute_tolerance_apm)
                          << " h_apm=unavailable vector_error_apm=unavailable"
                          << " estimator_roundoff_counts=see_refusal_exception\n";
            }
            // Do not reset or consume the original replay's lifetime counters.
            return {false, false};
        }
        const double elapsed_s = elapsed();
        require(result.h_xyz_apm.size() == 3u * call_targets.size() &&
                result.target_diagnostics.size() == call_targets.size(),
            "Stroud probe result shape is invalid");
        bool reference_pass = result.diagnostics.unconverged_pair_count == 0;
        for (std::size_t local = 0; local < call_targets.size(); ++local) {
            const auto index = first_reference + local;
            const Point h{result.h_xyz_apm[3u * local],
                result.h_xyz_apm[3u * local + 1u], result.h_xyz_apm[3u * local + 2u]};
            const double error_apm = field_distance(h, reference[index]);
            const double tolerance_apm = std::fma(options.relative_tolerance,
                field_distance(reference[index], Point{}), options.absolute_tolerance_apm);
            const bool target_pass = std::isfinite(error_apm) && error_apm <= tolerance_apm;
            reference_pass = reference_pass && target_pass;
            const auto &record = result.target_diagnostics[local];
            std::cerr << "OE-F1 STROUD_PROBE TARGET variant=" << variant
                      << " call=" << calls << " case=" << names[index]
                      << " status=" << (target_pass ? "REFERENCE_PASS" : "REFERENCE_FAIL")
                      << " target_m=";
            print_point(call_targets[local]);
            std::cerr << " h_apm=";
            print_point(h);
            std::cerr << " reference_h_apm=";
            print_point(reference[index]);
            std::cerr << " vector_error_apm=" << error_apm
                      << " reference_tolerance_apm=" << tolerance_apm
                      << " estimated_error_apm=" << record.estimated_error_apm
                      << " roundoff_indicator_apm=" << record.roundoff_indicator_apm
                      << " operator_tolerance_apm=" << record.tolerance_apm
                      << " final_leaves=" << record.final_leaf_count
                      << " target_kernels=" << record.kernel_evaluations
                      << " target_visits=" << record.ledger_leaf_visits << '\n';
        }
        const auto &diagnostics = result.diagnostics;
        std::cerr << "OE-F1 STROUD_PROBE CALL variant=" << variant
                  << " call=" << calls << " status=CONVERGED reference_status="
                  << (reference_pass ? "PASS" : "FAIL") << " elapsed_s=" << elapsed_s
                  << " source_target_pairs=" << diagnostics.source_target_pairs
                  << " refined_pairs=" << diagnostics.refined_pairs
                  << " unconverged_pairs=" << diagnostics.unconverged_pair_count
                  << " maximum_pair_error_apm=" << diagnostics.maximum_pair_error_apm
                  << " global_kernels=" << diagnostics.kernel_evaluations
                  << " global_visits=" << diagnostics.ledger_leaf_visits << '\n';
        return {true, reference_pass};
    };
    const auto batch = run("batch3", targets, 0);
    if (!batch.converged) {
        for (std::size_t index = 0; index < targets.size(); ++index) {
            (void)run(names[index], {targets[index]}, index);
        }
    }
    std::cerr << "OE-F1 STROUD_PROBE SUMMARY hypothesis="
              << (batch.converged && batch.reference_pass ? "BATCH_PASS" : "BATCH_FAIL")
              << " batch_converged=" << batch.converged
              << " batch_reference_pass=" << batch.reference_pass
              << " additional_calls=" << calls
              << " elapsed_s="
              << std::chrono::duration<double>(Clock::now() - probe_start).count()
              << " original_contract_outcome=FAIL original_exit=1\n";
}
#endif
